#![cfg(unix)]

use std::collections::HashMap;
use std::ffi::OsString;
use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::PathBuf;
use std::process::{Command, Output};
use tempfile::TempDir;

const HEADER_1: &str =
    "# EUC-JP vs Unicode mapping table, generated by tools/gen-euc-jp.py from glibc iconv EUC-JP.";
const HEADER_2: &str = "# Do not edit. Regenerate with: python3 tools/gen-euc-jp.py";

struct Fixture {
    root: TempDir,
    cwd: TempDir,
}

impl Fixture {
    fn new() -> Fixture {
        let root = TempDir::new().unwrap();
        fs::create_dir(root.path().join("tools")).unwrap();
        fs::create_dir(root.path().join("data")).unwrap();
        fs::write(
            root.path().join("tools/gen-euc-jp.py"),
            include_str!("../tools/gen-euc-jp.py"),
        )
        .unwrap();

        let bin = root.path().join("bin");
        fs::create_dir(&bin).unwrap();
        let iconv = bin.join("iconv");
        fs::write(&iconv, include_str!("../testdata/iconv-double.py")).unwrap();
        let mut permissions = fs::metadata(&iconv).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&iconv, permissions).unwrap();

        Fixture {
            root,
            cwd: TempDir::new().unwrap(),
        }
    }

    fn table(&self) -> PathBuf {
        self.root.path().join("data/euc-jp.txt")
    }

    fn run(&self, args: &[&str]) -> Output {
        self.run_with_fault(args, None)
    }

    fn run_with_fault(&self, args: &[&str], fault: Option<&str>) -> Output {
        let mut path = OsString::from(self.root.path().join("bin"));
        if let Some(existing) = std::env::var_os("PATH") {
            path.push(":");
            path.push(existing);
        }
        let mut command = Command::new("python3");
        command
            .arg("-I")
            .arg(self.root.path().join("tools/gen-euc-jp.py"))
            .args(args)
            .current_dir(self.cwd.path())
            .env("PATH", path)
            .env_remove("JISYO_TEST_ICONV_FAULT");
        if let Some(fault) = fault {
            command.env("JISYO_TEST_ICONV_FAULT", fault);
        }
        command.output().unwrap()
    }
}

fn ascii_rows() -> String {
    (0u32..=0x7F)
        .map(|code| format!("0x{code:02X}\tU+{code:04X}\n"))
        .collect()
}

fn generate(fixture: &Fixture) -> String {
    let output = fixture.run(&[]);
    assert_eq!(
        output.status.code(),
        Some(0),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    fs::read_to_string(fixture.table()).unwrap()
}

fn assert_rejected(fixture: &Fixture, fault: &str) {
    let sentinel = b"sentinel\n";
    fs::write(fixture.table(), sentinel).unwrap();
    let output = fixture.run_with_fault(&[], Some(fault));
    assert_eq!(
        output.status.code(),
        Some(1),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(output.stdout.is_empty());
    assert_eq!(String::from_utf8_lossy(&output.stderr), "error: iconv\n");
    assert_eq!(
        fs::read(fixture.table()).unwrap().as_slice(),
        sentinel.as_slice()
    );
}

#[test]
fn gen_writes_at_script_root() {
    let fixture = Fixture::new();
    let output = fixture.run(&[]);
    assert_eq!(
        output.status.code(),
        Some(0),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(
        String::from_utf8_lossy(&output.stdout),
        "wrote 131 mappings\n"
    );
    assert!(fixture.table().is_file());
    assert!(!fixture.cwd.path().join("data/euc-jp.txt").exists());
}

#[test]
fn gen_header() {
    let fixture = Fixture::new();
    let text = generate(&fixture);
    let expected = format!("{HEADER_1}\n{HEADER_2}\n");
    assert!(text.starts_with(&expected));
}

#[test]
fn gen_ascii_identity() {
    let fixture = Fixture::new();
    let text = generate(&fixture);
    let expected = format!("{HEADER_1}\n{HEADER_2}\n{}", ascii_rows());
    assert!(text.starts_with(&expected));
}

#[test]
fn gen_row_order() {
    let fixture = Fixture::new();
    let text = generate(&fixture);
    let mut actual = Vec::new();
    for line in text.split('\n') {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let code = line.split('\t').next().unwrap();
        actual.push(u32::from_str_radix(code.strip_prefix("0x").unwrap(), 16).unwrap());
    }
    let mut expected: Vec<u32> = (0..=0x7F).collect();
    expected.extend([0xA4A2, 0xFEFE, 0x8FA2B7]);
    assert_eq!(actual, expected);
}

#[test]
fn gen_codepoint_hex_width() {
    let fixture = Fixture::new();
    let text = generate(&fixture);
    let rows: HashMap<&str, &str> = text
        .split('\n')
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .map(|line| {
            let mut fields = line.split('\t');
            (fields.next().unwrap(), fields.next().unwrap())
        })
        .collect();
    assert_eq!(rows.get("0x00"), Some(&"U+0000"));
    assert_eq!(rows.get("0xA4A2"), Some(&"U+3042"));
    assert_eq!(rows.get("0xFEFE"), Some(&"U+20089"));
}

#[test]
fn gen_keeps_empty_record_positions() {
    let fixture = Fixture::new();
    let text = generate(&fixture);
    let rows: Vec<&str> = text
        .split('\n')
        .filter(|line| line.starts_with("0xA4A2\t"))
        .collect();
    assert_eq!(rows, ["0xA4A2\tU+3042"]);
}

#[test]
fn gen_rejects_multi_character() {
    let fixture = Fixture::new();
    let text = generate(&fixture);
    assert!(!text.split('\n').any(|line| line.starts_with("0xA4A3\t")));
}

#[test]
fn gen_rejects_reverse_mismatch() {
    let fixture = Fixture::new();
    let text = generate(&fixture);
    assert!(!text.split('\n').any(|line| line.starts_with("0x8EB1\t")));
}

#[test]
fn gen_check_matches() {
    let fixture = Fixture::new();
    let mut expected = format!("{HEADER_1}\n{HEADER_2}\n");
    expected.push_str(&ascii_rows());
    expected.push_str("0xA4A2\tU+3042\n0xFEFE\tU+20089\n0x8FA2B7\tU+FF5E\n");
    fs::write(fixture.table(), &expected).unwrap();
    let before = fs::metadata(fixture.table()).unwrap().modified().unwrap();

    let output = fixture.run(&["--check"]);
    assert_eq!(
        output.status.code(),
        Some(0),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(output.stdout.is_empty());
    assert!(output.stderr.is_empty());
    assert_eq!(fs::read_to_string(fixture.table()).unwrap(), expected);
    assert_eq!(
        fs::metadata(fixture.table()).unwrap().modified().unwrap(),
        before
    );
}

#[test]
fn gen_check_missing() {
    let fixture = Fixture::new();
    let output = fixture.run(&["--check"]);
    assert_eq!(output.status.code(), Some(1));
    assert!(output.stdout.is_empty());
    assert_eq!(
        String::from_utf8_lossy(&output.stderr),
        "data/euc-jp.txt is out of date\n"
    );
    assert!(!fixture.table().exists());
}

#[test]
fn gen_check_differs() {
    let fixture = Fixture::new();
    let sentinel = b"sentinel\n";
    fs::write(fixture.table(), sentinel).unwrap();

    let output = fixture.run(&["--check"]);
    assert_eq!(output.status.code(), Some(1));
    assert!(output.stdout.is_empty());
    assert_eq!(
        String::from_utf8_lossy(&output.stderr),
        "data/euc-jp.txt is out of date\n"
    );
    assert_eq!(
        fs::read(fixture.table()).unwrap().as_slice(),
        sentinel.as_slice()
    );
}

#[test]
fn gen_bad_argument() {
    let fixture = Fixture::new();
    let output = fixture.run(&["--unknown"]);
    assert_eq!(output.status.code(), Some(2));
    assert!(output.stdout.is_empty());
    assert_eq!(
        String::from_utf8_lossy(&output.stderr),
        "usage: gen-euc-jp.py [--check]\n"
    );
    assert!(!fixture.table().exists());
}

#[test]
fn gen_rejects_iconv_exit2() {
    assert_rejected(&Fixture::new(), "exit2");
}

#[test]
fn gen_rejects_iconv_stderr() {
    assert_rejected(&Fixture::new(), "stderr");
}

#[test]
fn gen_rejects_missing_lf() {
    assert_rejected(&Fixture::new(), "missing-lf");
}

#[test]
fn gen_rejects_extra_line() {
    assert_rejected(&Fixture::new(), "extra-line");
}
